[asy]
unitsize(1 cm);

pair moo (real t) {
 return (cos(t) + t/2, sin(t));
}

real t;
path foo = moo(-5/2*pi);

for (t = -5/2*pi; t <= 7/2*pi; t = t + 0.1) {
  foo = foo--moo(t);
}

