label("$B$",B, down);
label("$C$",C, left);
label("$X$",(1/3,0), down);
label("$Y$",(0,1/3), left);
label("$X'$", (1/3, 2/3), NE);
label("$Y'$", (2/3, 1/3), NE);
label("$X''$", (2/3, 0), down);
